#ifdef GL_ES
precision mediump float;
#endif

float hash21(vec2 p) {
    p = fract(p * 2345.6789);
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
}

float base21(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    float a = hash21(i);
    float b = hash21(i + vec2(1.0, 0.0));
    float c = hash21(i + vec2(0.0, 1.0));
    float d = hash21(i + vec2(1.0, 1.0));
    vec2 u = f * f * (3.0 - 2.0 * f);
    return mix(
        mix(a, b, u.x),
        mix(c, d, u.x),
        u.y
    );
}

float fbm21(vec2 p, float gain) {
    float val = 0.0;
    float amp = 1.0;
    float freq = 1.0;
    for(int i = 0; i < 4; i++) {
        val += amp * base21(p * freq);
        freq *= 2.01;
        amp *= gain;
    }
    return val / 2.0;
}

vec2 domainWarp(vec2 p, float time) {
    float n = fbm21(p + time * 0.2, 0.5) * 2.0 - 1.0; 
    float angle = n * 3.14159 * 2.0;
    vec2 dir = vec2(cos(angle), sin(angle));
    p += dir * 0.3 * n;
    return p;
}

float swirlAndStripes(vec2 uv, float time) {
    float r = length(uv);
    float theta = atan(uv.y, uv.x);
    theta += time * 0.4;
    float stripes = sin(10.0 * theta + 10.0 * r);
    vec2 warped = domainWarp(uv * 2.0, time);
    float noiseVal = fbm21(warped * 2.0, 0.5);
    float mixVal = noiseVal + 0.5 * stripes;
    return clamp(mixVal, 0.0, 1.0);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
    float time = iTime;
    float val = swirlAndStripes(uv, time);
    float t = 0.5 + 0.5 * sin(time * 0.5);
    val = smoothstep(t - 0.2, t + 0.2, val);
    vec3 colA = vec3(0.2, 0.4, 0.8);
    vec3 colB = vec3(0.0, 0.6, 1.0);
    vec3 color = mix(colA, colB, val);
    fragColor = vec4(color, 1.0);
}
